class AutoLayout(RemoteClass):
    """Core auto-layout engine.

    Public entry points:
     - AutoLayout.apply(slide, shapes, options)
     - Slide#autoLayout(shapes, options) → just forwards to AutoLayout.apply"""

    @classmethod
    def apply(
        cls, slide: Slide, shapes: list[Shape], options: None | AutoLayoutOptions = ...
    ) -> None:
        return RemoteClassAttr(cls, "apply")(slide, shapes, options)


